CREATE TABLE payments.intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid REFERENCES sales.orders(id), invoice_id uuid REFERENCES accounts.invoices(id), method text NOT NULL, amount_inc_vat_cents bigint NOT NULL, currency char(3) NOT NULL DEFAULT 'ZAR', provider text, status text NOT NULL DEFAULT 'created', idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid REFERENCES payments.intents(id), provider text NOT NULL, provider_ref text, amount_cents bigint NOT NULL, fee_cents bigint, status text NOT NULL, paid_at timestamptz, UNIQUE (provider, provider_ref));
CREATE TABLE payments.refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid REFERENCES payments.payments(id), amount_cents bigint NOT NULL, reason text, requested_by uuid NOT NULL, approved_by uuid, status text NOT NULL DEFAULT 'requested');
CREATE TABLE payments.provider_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, signature_ok boolean NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE (provider, event_id));
CREATE TABLE payments.settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, period_start date, period_end date, gross_cents bigint, fees_cents bigint, net_cents bigint, bank_ref text, matched boolean NOT NULL DEFAULT false);
CREATE TABLE payments.settlement_lines (settlement_id uuid REFERENCES payments.settlements(id), payment_id uuid REFERENCES payments.payments(id), amount_cents bigint, PRIMARY KEY (settlement_id, payment_id));
CREATE TABLE payments.payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payee_org_id uuid REFERENCES identity.orgs(id), amount_cents bigint NOT NULL, requested_by uuid NOT NULL, approved_by uuid, provider text, status text NOT NULL DEFAULT 'requested', paid_at timestamptz);
CREATE TABLE payments.escrow_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL DEFAULT 'tradesafe', buyer_org_id uuid, seller_org_id uuid, amount_cents bigint NOT NULL, state text NOT NULL, provider_ref text);
